#!/usr/bin/env python
"""DEX-SEC pre-commit hook.

Install it inside a repository with:

    python -m dexsec hook --install

It runs the static analysis on the staged files and refuses the commit when a
CRITICAL or HIGH finding is introduced.
"""

from __future__ import annotations

import os
import subprocess
import sys
import tempfile

HOOK_TEMPLATE = """#!/bin/sh
# DEX-SEC pre-commit hook (generated by `dexsec hook --install`)
{command}
"""


def staged_python_files(repo: str) -> list[str]:
    try:
        output = subprocess.run(
            ["git", "diff", "--cached", "--name-only", "--diff-filter=ACM"],
            cwd=repo,
            capture_output=True,
            text=True,
            check=False,
        ).stdout
    except OSError:
        return []
    return [line for line in output.splitlines() if line.strip()]


def run_analysis(repo: str, files: list[str]) -> tuple[int, str]:
    """Run DEX-SEC on the given files and return (exit code, report)."""
    from dexsec.core import correlator
    from dexsec.sast import scanner

    if not files:
        return 0, ""
    with tempfile.TemporaryDirectory() as tmp:
        for name in files:
            source = os.path.join(repo, name)
            if not os.path.isfile(source):
                continue
            target = os.path.join(tmp, name)
            os.makedirs(os.path.dirname(target), exist_ok=True)
            try:
                with open(source, "r", encoding="utf-8", errors="ignore") as fh:
                    content = fh.read()
            except OSError:
                continue
            with open(target, "w", encoding="utf-8") as fh:
                fh.write(content)
        _routes, findings, _frameworks = scanner.scan_project(tmp)
        correlated = correlator.correlate(findings, [])
        blocking = [
            item for item in correlated
            if item.final_severity.value in ("CRITICAL", "HIGH") and item.status.value != "NOT_REPRODUCIBLE"
        ]
        if not blocking:
            return 0, ""
        lines = ["DEX-SEC blocked the commit:", ""]
        for item in blocking:
            lines.append(f"  [{item.final_severity.value}] {item.title}")
            lines.append(f"      {item.remediation_hint}")
        lines += ["", "Fix the issues or run:  dexsec scan --path . --skip-dast"]
        return 1, "\n".join(lines)


def install_hook(repo: str | None = None) -> str:
    """Install the pre-commit hook into .git/hooks."""
    repo = repo or os.getcwd()
    hooks_dir = os.path.join(repo, ".git", "hooks")
    if not os.path.isdir(hooks_dir):
        raise RuntimeError(f"not a git repository: {repo}")
    hook_path = os.path.join(hooks_dir, "pre-commit")
    command = 'exec dexsec hook --run "$(git diff --cached --name-only --diff-filter=ACM)"'
    with open(hook_path, "w", encoding="utf-8", newline="\n") as fh:
        fh.write(HOOK_TEMPLATE.format(command=command))
    os.chmod(hook_path, 0o755)
    return hook_path


def run_hook(files: list[str] | None = None) -> int:
    repo = os.getcwd()
    if files is None:
        files = staged_python_files(repo)
    code, report = run_analysis(repo, files)
    if report:
        print(report, file=sys.stderr)
    return code


if __name__ == "__main__":
    raise SystemExit(run_hook(sys.argv[1:]))
